fn text(value:&str,c:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{Ok(DslValue::String(c.copy_text(value)?))}
fn project(value:&SpaceHistorySnapshot,c:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{
 c.begin_stage(0)?;let mut checkpoints=c.allocate_vec(value.checkpoints.len())?;
 for row in&value.checkpoints{
  let mut authors=c.allocate_vec(row.authors.len())?;for author in&row.authors{let mut fields=c.allocate_vec(if author.avatar.is_some(){3}else{2})?;fields.push((c.copy_text("id")?,text(&author.id,c)?));fields.push((c.copy_text("name")?,text(&author.name,c)?));if let Some(avatar)=&author.avatar{fields.push((c.copy_text("avatar")?,text(avatar,c)?));}authors.push(DslValue::Object(fields));c.step()?;}
  let timestamp=object([("actor",DslValue::uint(row.timestamp.actor)),("physical_ms",DslValue::uint(row.timestamp.physical_ms)),("logical",DslValue::uint(row.timestamp.logical))],c)?;
  let mut members=c.allocate_vec(row.members.len())?;for pin in&row.members{members.push(object([("documentId",text(&pin.document_id,c)?),("checkpointId",text(&pin.checkpoint_id,c)?),("alternativeId",text(&pin.alternative_id,c)?)],c)?);c.step()?;}
