 }
 let mut alternatives=c.allocate_vec(list(field(value,"alternatives")?)?.len())?;for row in list(field(value,"alternatives")?)?{let mut checkpoint_ids=c.allocate_vec(list(field(row,"checkpointIds")?)?.len())?;for pin in list(field(row,"checkpointIds")?)?{checkpoint_ids.push(String::from_value_controlled(pin,c)?);c.step()?;}alternatives.push(SpaceAlternative{id:string(row,"id",c)?,name:string(row,"name",c)?,checkpoint_ids});c.step()?;}
