//! 🔗️ Bounded ordinal and literal cell construction for explicitly named space entities.
use semio_framework_os_kernel::{os_dsl::NativeDecodeControl,sqlite_snapshot::{SqliteRow,SqliteTable}};
use semio_framework_value::{ValueError,ValueRefusalKind};
pub(crate) fn invalid(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
pub(crate) fn reconstruct<T>(control:&mut semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotControl<'_>,operation:impl FnOnce(&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<T,ValueError>{
 let maximum=control.reconstruction_remaining_bytes()?;
 let(result,owned)={
  let mut progress=|event:semio_framework_value::native_decoding::NativeDecodeProgress|control.checkpoint(semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotPhase::ReconstructSnapshot,event.completed,event.total).is_ok();
  let mut native=NativeDecodeControl::new(maximum,&mut progress);let result=operation(&mut native);(result,native.owned_bytes())
 };
 control.admit_reconstruction_bytes(owned)?;result
}
pub(crate) fn ordinal(value:usize)->Result<i64,ValueError>{i64::try_from(value).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"space ordinal exceeds SQLite INTEGER"))}
pub(crate) fn keyed<'a>(table:&'a SqliteTable,width:usize,control:&mut NativeDecodeControl<'_>)->Result<Vec<&'a SqliteRow>,ValueError>{control.scoped_stage(|control|{control.begin_stage(0)?;let mut rows=control.allocate_vec(table.rows.len())?;for row in&table.rows{if row.values.len()!=width||row.integer(0)?!=row.rowid{return Err(invalid("space body identity differs"))}rows.push(row);control.step()?;}fn sift(rows:&mut[&SqliteRow],mut root:usize,end:usize,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{while root<end/2{control.step()?;let mut child=root*2+1;if child+1<end&&rows[child].rowid<rows[child+1].rowid{child+=1;}if rows[root].rowid>=rows[child].rowid{break}rows.swap(root,child);root=child;}Ok(())}let count=rows.len();for root in(0..count/2).rev(){sift(&mut rows,root,count,control)?;}for end in(1..count).rev(){control.step()?;rows.swap(0,end);sift(&mut rows,0,end,control)?;}for index in 1..count{if rows[index-1].rowid==rows[index].rowid{return Err(invalid("space body identity is duplicated"))}control.step()?;}Ok(rows)})}
pub(crate) fn ordered<'a>(table:&'a SqliteTable,parent:i64,width:usize,control:&mut NativeDecodeControl<'_>)->Result<Vec<&'a SqliteRow>,ValueError>{
 control.scoped_stage(|control|{
  let keyed=keyed(table,width,control)?;control.begin_stage(table.rows.len())?;let mut slots=control.allocate_vec::<Option<&SqliteRow>>(table.rows.len())?;slots.resize(table.rows.len(),None);
  for row in keyed{if row.integer(1)?!=parent{return Err(invalid("space entity ownership differs"))}let index=usize::try_from(row.integer(2)?).map_err(|_|invalid("space ordinal must be nonnegative"))?;let slot=slots.get_mut(index).ok_or_else(||invalid("space ordinal must be contiguous"))?;if slot.replace(row).is_some(){return Err(invalid("space ordinal is duplicated"))}control.step()?;}
  let mut rows=control.allocate_vec(slots.len())?;for row in slots{rows.push(row.ok_or_else(||invalid("space ordinal must be contiguous"))?);}Ok(rows)
 })
}
pub(crate) fn text(row:&SqliteRow,index:usize,control:&mut NativeDecodeControl<'_>)->Result<String,ValueError>{control.copy_text(row.text(index)?)}
pub(crate) fn optional(row:&SqliteRow,index:usize,control:&mut NativeDecodeControl<'_>)->Result<Option<String>,ValueError>{row.optional_text(index)?.map(|text|control.copy_text(text)).transpose()}
pub(crate) fn list_count(record:&semio_framework_os_kernel::os_dsl::RecordValue,id:u16)->Result<usize,ValueError>{match record.get(id){Some(semio_framework_os_kernel::os_dsl::FieldValue::List(values))=>Ok(values.len()),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue, "space native field requires its declared list"))}}
pub(crate) fn add(left:usize,right:usize)->Result<usize,ValueError>{left.checked_add(right).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit, "space row count overflow"))}
pub(crate) fn grouped<'a>(table:&'a SqliteTable,width:usize,parents:&[&SqliteRow],control:&mut NativeDecodeControl<'_>)->Result<Vec<Vec<&'a SqliteRow>>,ValueError>{
 control.scoped_stage(|control|{
  let rows=keyed(table,width,control)?;let mut counts=control.allocate_vec::<usize>(parents.len())?;counts.resize(parents.len(),0);
  control.begin_stage(rows.len())?;for row in&rows{let owner=parents.binary_search_by_key(&row.integer(1)?,|parent|parent.rowid).map_err(|_|invalid("space child owner is missing"))?;counts[owner]=counts[owner].checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"space row count overflow"))?;control.step()?;}
  let mut slots=control.allocate_vec::<Vec<Option<&SqliteRow>>>(parents.len())?;control.begin_stage(parents.len())?;for count in counts{let mut group=control.allocate_vec(count)?;group.resize(count,None);slots.push(group);control.step()?;}
  control.begin_stage(rows.len())?;for row in rows{let owner=parents.binary_search_by_key(&row.integer(1)?,|parent|parent.rowid).map_err(|_|invalid("space child owner is missing"))?;let index=usize::try_from(row.integer(2)?).map_err(|_|invalid("space child ordinal must be nonnegative"))?;let slot=slots[owner].get_mut(index).ok_or_else(||invalid("space child ordinal must be contiguous"))?;if slot.replace(row).is_some(){return Err(invalid("space child ordinal is duplicated"))}control.step()?;}
  let mut groups=control.allocate_vec(parents.len())?;control.begin_stage(table.rows.len())?;for group in slots{let mut rows=control.allocate_vec(group.len())?;for row in group{rows.push(row.ok_or_else(||invalid("space child ordinal must be contiguous"))?);control.step()?;}groups.push(rows);}Ok(groups)
 })
}
