#[test]
fn sqlite_snapshot_framework_space_history_native_input_retained_materialization_uses_same_caller_ledger(){
 let corpus=f();let sample=&corpus["interiorControl"];let ratio=&corpus["nativeRetention"];let mut source=fixture();source.checkpoints[0].message=sample["textUnit"].as_str().unwrap().repeat(sample["repeat"].as_u64().unwrap()as usize);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=payload(&source,encoding);let limits=SqliteDatabaseLimits::default();let mut progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut progress,limits);let first=<SpaceHistorySnapshot as store::ArtifactSqliteSnapshot>::decode_sqlite_snapshot_native(&payload,&mut control).unwrap();assert_eq!(first,source);let charged=limits.max_value_bytes-control.reconstruction_remaining_bytes().unwrap();assert!(charged>0,"native parser and retained typed fields must publish their actual cumulative ownership");
  let ceiling=charged.checked_mul(ratio["ceilingNumerator"].as_u64().unwrap()as usize).unwrap()/ratio["ceilingDenominator"].as_u64().unwrap()as usize;let limits=SqliteDatabaseLimits{max_value_bytes:ceiling,..limits};let mut progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut progress,limits);let retained=<SpaceHistorySnapshot as store::ArtifactSqliteSnapshot>::decode_sqlite_snapshot_native(&payload,&mut control).unwrap();assert_eq!(retained,source);assert!(<SpaceHistorySnapshot as store::ArtifactSqliteSnapshot>::decode_sqlite_snapshot_native(&payload,&mut control).is_err(),"second retained native input must not reset the same caller ledger");
 }
}

//! 🚦️ Controlled existing JSON text and raw value-Pack carriers of space history.
use super::*;
use semio_framework_value::{DslValue,NativeDecodeControl,NativeEncodeControl,FromValue,ValueError,ValueRefusalKind};
use crate::os_dsl::{FieldValue,RecordLayout,RecordSpec,Shape,NativeSchemaControl};
use crate::os_dsl::native_encoding::EncodedRecord;
fn spec<C:NativeSchemaControl>(c:&mut C)->Result<RecordSpec,ValueError>{let mut fields=c.allocate_vec(1)?;fields.push(crate::os_dsl::schema::producer::field(1,"value",Shape::Value,c)?);crate::os_dsl::schema::producer::record(None,RecordLayout::Lines,fields,c)}
fn add(left:usize,right:usize)->Result<usize,ValueError>{left.checked_add(right).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"space row count overflow"))}
fn object<const N:usize>(fields:[(&str,DslValue);N],c:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{let mut values=c.allocate_vec(N)?;for(key,value)in fields{values.push((c.copy_text(key)?,value));}Ok(DslValue::Object(values))}
fn text(value:&str,c:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{Ok(DslValue::String(c.copy_text(value)?))}
fn project(value:&SpaceHistorySnapshot,c:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{
 c.begin_stage(0)?;let mut checkpoints=c.allocate_vec(value.checkpoints.len())?;
 for row in&value.checkpoints{
  let mut authors=c.allocate_vec(row.authors.len())?;for author in&row.authors{let mut fields=c.allocate_vec(if author.avatar.is_some(){3}else{2})?;fields.push((c.copy_text("id")?,text(&author.id,c)?));fields.push((c.copy_text("name")?,text(&author.name,c)?));if let Some(avatar)=&author.avatar{fields.push((c.copy_text("avatar")?,text(avatar,c)?));}authors.push(DslValue::Object(fields));c.step()?;}
  let timestamp=object([("actor",DslValue::uint(row.timestamp.actor)),("physical_ms",DslValue::uint(row.timestamp.physical_ms)),("logical",DslValue::uint(row.timestamp.logical))],c)?;
  let mut members=c.allocate_vec(row.members.len())?;for pin in&row.members{members.push(object([("documentId",text(&pin.document_id,c)?),("checkpointId",text(&pin.checkpoint_id,c)?),("alternativeId",text(&pin.alternative_id,c)?)],c)?);c.step()?;}
  let mut fields=c.allocate_vec(if row.parent_id.is_some(){6}else{5})?;fields.push((c.copy_text("id")?,text(&row.id,c)?));if let Some(parent)=&row.parent_id{fields.push((c.copy_text("parentId")?,text(parent,c)?));}fields.push((c.copy_text("message")?,text(&row.message,c)?));fields.push((c.copy_text("authors")?,DslValue::Array(authors)));fields.push((c.copy_text("timestamp")?,timestamp));fields.push((c.copy_text("members")?,DslValue::Array(members)));checkpoints.push(DslValue::Object(fields));c.step()?;
 }
 let mut alternatives=c.allocate_vec(value.alternatives.len())?;for row in&value.alternatives{let mut pins=c.allocate_vec(row.checkpoint_ids.len())?;for pin in&row.checkpoint_ids{pins.push(text(pin,c)?);c.step()?;}alternatives.push(object([("id",text(&row.id,c)?),("name",text(&row.name,c)?),("checkpointIds",DslValue::Array(pins))],c)?);c.step()?;}
 let mut fields=c.allocate_vec(if value.active_alternative_id.is_some(){3}else{2})?;fields.push((c.copy_text("checkpoints")?,DslValue::Array(checkpoints)));fields.push((c.copy_text("alternatives")?,DslValue::Array(alternatives)));if let Some(active)=&value.active_alternative_id{fields.push((c.copy_text("activeAlternativeId")?,text(active,c)?));}Ok(DslValue::Object(fields))
}
fn field<'a>(value:&'a DslValue,key:&str)->Result<&'a DslValue,ValueError>{let DslValue::Object(fields)=value else{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"space history native object is required"))};fields.iter().find(|(name,_)|name==key).map(|(_,value)|value).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,format!("space history native field {key} is required")))}
fn list(value:&DslValue)->Result<&[DslValue],ValueError>{match value{DslValue::Array(values)=>Ok(values),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"space history native list is required"))}}
fn optional(value:&DslValue,key:&str,c:&mut NativeDecodeControl<'_>)->Result<Option<String>,ValueError>{let DslValue::Object(fields)=value else{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"space history native object is required"))};match fields.iter().find(|(name,_)|name==key).map(|(_,value)|value){None|Some(DslValue::Null)=>Ok(None),Some(value)=>Ok(Some(String::from_value_controlled(value,c)?))}}
fn string(value:&DslValue,key:&str,c:&mut NativeDecodeControl<'_>)->Result<String,ValueError>{String::from_value_controlled(field(value,key)?,c)}
fn census(value:&DslValue,maximum:usize,c:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{
 let checkpoints=list(field(value,"checkpoints")?)?;let alternatives=list(field(value,"alternatives")?)?;c.begin_stage(add(checkpoints.len(),alternatives.len())?)?;let mut count=1;
 for row in checkpoints{count=add(count,add(2,add(list(field(row,"authors")?)?.len(),list(field(row,"members")?)?.len())?)?)?;if count>maximum{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"space history semantic row limit exceeded"))}c.step()?;}
 for row in alternatives{count=add(count,add(1,list(field(row,"checkpointIds")?)?.len())?)?;if count>maximum{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"space history semantic row limit exceeded"))}c.step()?;}if count>maximum{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"space history semantic row limit exceeded"))}Ok(())
}
fn construct(value:&DslValue,c:&mut NativeDecodeControl<'_>)->Result<SpaceHistorySnapshot,ValueError>{
 c.begin_stage(0)?;c.charge(std::mem::size_of::<SpaceHistorySnapshot>())?;let mut checkpoints=c.allocate_vec(list(field(value,"checkpoints")?)?.len())?;
 for row in list(field(value,"checkpoints")?)?{
  let mut authors=c.allocate_vec(list(field(row,"authors")?)?.len())?;for author in list(field(row,"authors")?)?{authors.push(Author{id:string(author,"id",c)?,name:string(author,"name",c)?,avatar:optional(author,"avatar",c)?});c.step()?;}
  let clock=field(row,"timestamp")?;let timestamp=HybridLogicalTimestamp{actor:u64::from_value_controlled(field(clock,"actor")?,c)?,physical_ms:u64::from_value_controlled(field(clock,"physical_ms")?,c)?,logical:u64::from_value_controlled(field(clock,"logical")?,c)?};
  let mut members=c.allocate_vec(list(field(row,"members")?)?.len())?;for pin in list(field(row,"members")?)?{members.push(SpaceMemberPin{document_id:string(pin,"documentId",c)?,checkpoint_id:string(pin,"checkpointId",c)?,alternative_id:match field(pin,"alternativeId"){Ok(_)=>string(pin,"alternativeId",c)?,Err(_)=>String::new()}});c.step()?;}
  checkpoints.push(SpaceCheckpoint{id:string(row,"id",c)?,parent_id:optional(row,"parentId",c)?,message:string(row,"message",c)?,authors,timestamp,members});c.step()?;
 }
 let mut alternatives=c.allocate_vec(list(field(value,"alternatives")?)?.len())?;for row in list(field(value,"alternatives")?)?{let mut checkpoint_ids=c.allocate_vec(list(field(row,"checkpointIds")?)?.len())?;for pin in list(field(row,"checkpointIds")?)?{checkpoint_ids.push(String::from_value_controlled(pin,c)?);c.step()?;}alternatives.push(SpaceAlternative{id:string(row,"id",c)?,name:string(row,"name",c)?,checkpoint_ids});c.step()?;}
 Ok(SpaceHistorySnapshot{checkpoints,alternatives,active_alternative_id:optional(value,"activeAlternativeId",c)?})
}
fn string_size(text:&str,c:&mut NativeEncodeControl<'_>)->Result<usize,ValueError>{c.scoped_stage(|c|{c.begin_stage(text.len())?;let mut bytes=2usize;for character in text.chars(){let size=match character{'\\'|'"'|'\n'|'\r'|'\t'|'\u{0008}'|'\u{000c}'=>2,character if character<' '=>6,_=>character.len_utf8()};bytes=add(bytes,size)?;c.advance(character.len_utf8())?;}Ok(bytes)})}
fn json_size(value:&DslValue,c:&mut NativeEncodeControl<'_>)->Result<usize,ValueError>{c.step()?;match value{DslValue::String(text)=>string_size(text,c),DslValue::Number(semio_framework_value::Number::UInt(value))=>{let mut count=1;let mut value=*value;while value>=10{value/=10;count+=1;}Ok(count)},DslValue::Array(values)=>{let mut count=add(2,values.len().saturating_sub(1))?;for value in values{count=add(count,json_size(value,c)?)?;}Ok(count)},DslValue::Object(values)=>{let mut count=add(2,values.len().saturating_sub(1))?;for(key,value)in values{count=add(count,add(string_size(key,c)?,add(1,json_size(value,c)?)?)?)?;}Ok(count)},_=>Err(ValueError::new(ValueRefusalKind::InvariantViolated,"space history projector emitted an undeclared native primitive"))}}
pub(super) fn encode(value:&SpaceHistorySnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<crate::io_schema::IoPayload,ValueError>{
 let limits=control.limits();control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;let mut progress=|event:semio_framework_value::native_encoding::NativeEncodeProgress|control.checkpoint(SqliteSnapshotPhase::EncodeNative,event.completed,event.total).is_ok();let mut c=NativeEncodeControl::new(limits.max_value_bytes,&mut progress);let value=project(value,&mut c)?.guard_decoded();
 match encoding{SnapshotEncoding::Text=>{c.begin_stage(0)?;if json_size(value.get(),&mut c)?>limits.max_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit, "space history native text exceeds file limit"))}Ok(crate::io_schema::IoPayload::Text(semio_framework_pack_json::to_json_string_controlled(value.get(),&mut c)?))},SnapshotEncoding::Binary=>{let spec=spec(&mut c)?;let mut record=EncodedRecord::new(1,&mut c)?;record.insert(1,FieldValue::Value(value.take()))?;let mut options=crate::os_store::PackEncodeOptions::default();options.limits.max_file_len=limits.max_file_bytes as u64;Ok(crate::io_schema::IoPayload::Binary(crate::os_pack::encode_document_controlled(&spec,record.as_record(),&options,&mut c).map_err(crate::os_store::PackError::into_value_error)?))}}
}
pub(super) fn decode(payload:&crate::io_schema::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SpaceHistorySnapshot,ValueError>{
 let limits=control.limits();control.checkpoint(SqliteSnapshotPhase::DecodeNative,0,0)?;let length=match payload{crate::io_schema::IoPayload::Text(text)=>text.len(),crate::io_schema::IoPayload::Binary(bytes)=>bytes.len()};if length>limits.max_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit, "space history native input exceeds file limit"))}
 let mut progress=|event:semio_framework_value::native_decoding::NativeDecodeProgress|control.checkpoint(SqliteSnapshotPhase::DecodeNative,event.completed,event.total).is_ok();let mut c=NativeDecodeControl::new(limits.max_value_bytes,&mut progress);
 match payload{
  crate::io_schema::IoPayload::Text(text)=>{let value=semio_framework_pack_json::from_json_str_controlled::<DslValue>(text,semio_framework_pack_json::JsonMemberPolicy::Reject,&mut c)?.guard_decoded();census(value.get(),limits.max_rows,&mut c)?;construct(value.get(),&mut c)},
  crate::io_schema::IoPayload::Binary(bytes)=>{let spec=spec(&mut c)?;let(record,_)=crate::os_store::pack_rt::decode_document_controlled(bytes,&spec,&crate::os_store::PackDecodeOptions::default(),&mut c).map_err(crate::os_store::PackError::into_value_error)?;let Some(FieldValue::Value(value))=record.get(1)else{return Err(ValueError::new(ValueRefusalKind::InvalidValue, "space history native value field is missing"))};census(&value,limits.max_rows,&mut c)?;construct(&value,&mut c)}
 }
}
